#!/usr/bin/env python3
"""run-dev-graph-init applier: idempotent, preview-first, fail-closed.

Implements the SKILL execution contract steps 2-5 for R2/R3/R4/R5 using the
C24 receipt produced by resolve-repo-context.py as the only write authority.
Stored paths are repository-relative; no absolute path, token or node ID is
persisted into repo-local artifacts.
"""
from __future__ import annotations

import argparse
import copy
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
from pathlib import Path
from typing import Any

PLUGIN_ROOT = Path("/Users/dm/orca/workspaces/harness/ジャーナル作成/plugins/dev-graph")
sys.path.insert(0, str(PLUGIN_ROOT / "scripts"))
from _common import ContractError, contained, load_json  # noqa: E402

CONTENT_ROOTS = {
    "issues": "issues",
    "tasks": "tasks",
    "specifications": "specs",
    "architecture": "architecture",
    "features": "features",
    "documents": "docs",
    "system_spec": "system-spec",
}
LOCAL_STATE = {
    "graph": ".dev-graph/state/graph.json",
    "cache": ".dev-graph/cache",
    "locks": ".dev-graph/locks",
}
TEMPLATES_ROOT = ".dev-graph/templates"
CONFIG_PATH = ".dev-graph/config.json"
SECRET_PATTERNS = [
    r"gh[pousr]_[A-Za-z0-9]{16,}",
    r"github_pat_[A-Za-z0-9_]{20,}",
    r"\bPVT_[A-Za-z0-9_-]{8,}",
    r"\bPVTI_[A-Za-z0-9_-]{8,}",
    r"\bPVTF_[A-Za-z0-9_-]{8,}",
    r"\bI_kw[A-Za-z0-9_-]{8,}",
    r"\bMDU6[A-Za-z0-9_-]{8,}",
    r"\bPR_kw[A-Za-z0-9_-]{8,}",
    r"\bghs_[A-Za-z0-9]{16,}",
]
HOOK_EVENTS = ("PreToolUse", "SessionStart", "PostToolUse", "TaskCompleted")


def digest_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def digest_file(path: Path) -> str:
    return digest_bytes(path.read_bytes())


def canonical_json_bytes(value: Any) -> bytes:
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode("utf-8")


def build_config(repository_id: str) -> dict[str, Any]:
    """GitHub publication stays disabled; only owner/number/field names are stored."""
    return {
        "schema_version": "1.0.0",
        "repository_id": repository_id,
        "content_roots": dict(CONTENT_ROOTS),
        "local_state": dict(LOCAL_STATE),
        "github": {
            "enabled": False,
            "issue_repository": "owner/repository",
            "projects": [
                {
                    "alias": "delivery",
                    "owner_type": "organization",
                    "owner_login": "owner",
                    "project_number": 1,
                    "default": True,
                    "auto_add": {
                        "artifact_kinds": ["task"],
                        "confirmation_status": "confirmed",
                        "evaluation_status": "pass",
                        "implementation_readiness": "complete",
                    },
                    "field_mappings": [
                        {
                            "local_field": "status",
                            "project_field_name": "Status",
                            "value_type": "single_select",
                            "direction": "local_to_project",
                            "option_map": {"active": "In Progress", "blocked": "Blocked", "done": "Done"},
                        },
                        {
                            "local_field": "priority",
                            "project_field_name": "Priority",
                            "value_type": "single_select",
                            "direction": "bidirectional",
                            "option_map": {"high": "High", "medium": "Medium", "low": "Low"},
                        },
                    ],
                }
            ],
            "completion_policy": {
                "trigger": "linked_pr_merged",
                "required_pull_requests": "all",
                "target_branch": "default",
                "closed_unmerged": "keep_active",
                "issue_reopened": "reopen_task",
                "revert": "create_follow_up_unless_issue_reopened",
                "local_reconciliation": ["manual_sync", "claude_hook"],
                "scheduled_reconciliation": {
                    "enabled": False,
                    "interval_minutes": 60,
                    "owner": "claude_session_start",
                    "entry_point": "dev-graph sync --reconcile-lifecycle",
                },
            },
        },
        "execution_tracker": {
            "mode": "beads",
            "beads": {
                "issue_prefix": "devgraph",
                "server_mode": False,
                "github_mirror": "none",
                "board": "static-render",
            },
        },
        "worktrees": {
            "enabled": True,
            "lease_ttl_seconds": 1800,
            "heartbeat_seconds": 60,
            "coordination_store": "git_common_dir",
            "completion_write_branch": "default",
            "dirty_worktree_policy": "fail_closed",
        },
        "claude_hooks": {
            "source": "plugin",
            "project_plugin_link": ".claude/dev-graph-plugin",
            "session_start": True,
            "post_tool_reconcile": True,
            "task_completed_gate": True,
        },
        "path_policy": {
            "authority": "caller-repository",
            "stored_paths": "repository-relative",
            "allow_outside_repository": False,
            "follow_content_symlinks_outside_repository": False,
        },
    }


def template_assets(contract: dict[str, Any]) -> tuple[list[str], list[str]]:
    """Return (contract-enumerated templates, all shipped template files)."""
    enumerated: set[str] = set()
    common = (contract.get("common_frontmatter") or {}).get("template")
    if common:
        enumerated.add(common)
    for spec in (contract.get("artifacts") or {}).values():
        for key in ("template",):
            if spec.get(key):
                enumerated.add(spec[key])
        for group in ("conditional_templates", "subtype_templates"):
            for value in (spec.get(group) or {}).values():
                enumerated.add(value)
    projection = (contract.get("graph_projection") or {}).get("template")
    if projection:
        enumerated.add(projection)
    plan = contract.get("system_plan") or {}
    for key in ("phase_template", "task_overlay"):
        value = plan.get(key)
        if isinstance(value, str) and value.endswith(".md"):
            enumerated.add(value)
    shipped = sorted(p.name for p in (PLUGIN_ROOT / "templates").iterdir() if p.is_file())
    return sorted(enumerated), shipped


def classify(target: Path, expected: bytes | None, kind: str, relative: str, plan: dict[str, list]) -> None:
    """Preview one asset without writing: create / preserve / user-modified."""
    if kind == "directory":
        if target.is_dir():
            plan["preserved"].append({"path": relative, "kind": kind})
        elif target.exists():
            raise ContractError(f"expected directory but found file: {relative}")
        else:
            plan["create"].append({"path": relative, "kind": kind})
        return
    if target.is_symlink():
        raise ContractError(f"repo-local asset must not be a symlink: {relative}")
    if target.is_file():
        actual = digest_file(target)
        if expected is not None and actual == digest_bytes(expected):
            plan["preserved"].append({"path": relative, "kind": kind, "sha256": actual})
        else:
            plan["migration_preview"].append(
                {
                    "path": relative,
                    "kind": kind,
                    "reason": "user_modified",
                    "existing_sha256": actual,
                    "plugin_sha256": digest_bytes(expected) if expected is not None else None,
                    "action": "preserve_without_overwrite",
                }
            )
        return
    plan["create"].append({"path": relative, "kind": kind, "sha256": digest_bytes(expected or b"")})


def hook_state(root: Path, hook_source: str) -> dict[str, Any]:
    """C25 plugin hook is the shared default; project fallback is refused here."""
    plugin_hooks = load_json(PLUGIN_ROOT / "hooks" / "hooks.json")
    events = sorted((plugin_hooks.get("hooks") or {}).keys())
    settings = root / ".claude" / "settings.json"
    project_entries: list[str] = []
    if settings.is_file():
        data = load_json(settings)
        for event, blocks in ((data.get("hooks") or {}) if isinstance(data, dict) else {}).items():
            for block in blocks if isinstance(blocks, list) else []:
                for hook in (block or {}).get("hooks", []):
                    if "dev-graph" in json.dumps(hook, ensure_ascii=False):
                        project_entries.append(event)
    state = {
        "requested_source": hook_source,
        "effective_source": "plugin",
        "plugin_managed": True,
        "plugin_hook_events": events,
        "plugin_hook_events_complete": sorted(HOOK_EVENTS) == events,
        "project_settings_present": settings.is_file(),
        "project_fallback_entries": sorted(set(project_entries)),
        "project_fallback_decision": "refused_effective_plugin_hook_present",
        "double_registration": bool(project_entries),
        "settings_writes": 0,
        "rollback_manifest": None,
    }
    if hook_source != "plugin":
        raise ContractError(f"unsupported hook source for this trial: {hook_source}")
    if not state["plugin_hook_events_complete"]:
        raise ContractError(f"plugin hook does not cover all C10/C25 events: {events}")
    if state["double_registration"]:
        raise ContractError(f"double hook registration detected: {state['project_fallback_entries']}")
    return state


def scan_forbidden(root: Path, paths: list[str]) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    for relative in paths:
        target = root / relative
        if not target.is_file():
            continue
        text = target.read_text(encoding="utf-8")
        for match in re.finditer(r"(?<![\w.-])/(?:Users|home|private|var|tmp|opt|etc)/[\w./-]+", text):
            findings.append({"path": relative, "code": "absolute_path", "detail": match.group(0)})
        if str(root) in text:
            findings.append({"path": relative, "code": "absolute_path", "detail": "repo root literal"})
        for pattern in SECRET_PATTERNS:
            for match in re.finditer(pattern, text):
                findings.append({"path": relative, "code": "secret_or_node_id", "detail": pattern})
    return findings


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--context", required=True, help="C24 receipt JSON path")
    parser.add_argument("--hook-source", default="plugin")
    parser.add_argument("--apply", action="store_true")
    parser.add_argument("--receipt", required=True)
    args = parser.parse_args()

    context = load_json(Path(args.context))
    if context.get("mode") != "write":
        raise ContractError("C24 receipt was not produced in write mode")
    root = Path(context["repo_root"]).resolve(strict=True)
    if Path(context["content_roots"]["repository"]).resolve(strict=True) != root:
        raise ContractError("C24 repo_root does not match content authority realpath")
    actual_top = subprocess.run(
        ["git", "-C", str(root), "rev-parse", "--show-toplevel"], text=True, capture_output=True, check=True
    ).stdout.strip()
    if Path(actual_top).resolve(strict=True) != root:
        raise ContractError("resolved root is not the host project/worktree root")
    if Path(context["plugin_source"]).resolve(strict=True) != PLUGIN_ROOT.resolve(strict=True):
        raise ContractError("plugin code authority mismatch")
    try:
        PLUGIN_ROOT.resolve(strict=True).relative_to(root)
    except ValueError:
        pass
    else:
        raise ContractError("plugin source must not be inside the content authority")

    repository_id = context["repository_id"]
    contract = load_json(PLUGIN_ROOT / "templates" / "template-contract.json")
    enumerated, shipped = template_assets(contract)
    missing_from_plugin = [name for name in enumerated if not (PLUGIN_ROOT / "templates" / name).is_file()]
    if missing_from_plugin:
        raise ContractError(f"template contract enumerates missing plugin assets: {missing_from_plugin}")

    config_value = build_config(repository_id)
    config_bytes = canonical_json_bytes(config_value)
    graph_bytes = canonical_json_bytes({"graph_revision": 0, "nodes": []})

    plan: dict[str, list] = {"create": [], "preserved": [], "migration_preview": []}
    assets: list[tuple[str, str, bytes | None]] = []
    for relative in sorted(CONTENT_ROOTS.values()):
        assets.append((relative, "directory", None))
        assets.append((f"{relative}/.gitkeep", "content_root_keep", b""))
    assets.append((".dev-graph", "directory", None))
    assets.append((".dev-graph/state", "directory", None))
    assets.append((LOCAL_STATE["cache"], "directory", None))
    assets.append((LOCAL_STATE["locks"], "directory", None))
    assets.append((TEMPLATES_ROOT, "directory", None))
    assets.append((CONFIG_PATH, "config", config_bytes))
    assets.append((LOCAL_STATE["graph"], "graph_store", graph_bytes))
    for name in shipped:
        assets.append((f"{TEMPLATES_ROOT}/{name}", "template", (PLUGIN_ROOT / "templates" / name).read_bytes()))

    for relative, kind, expected in assets:
        target = contained(root / relative, root, must_exist=False)
        classify(target, expected, kind, relative, plan)

    hooks = hook_state(root, args.hook_source)
    planned_changes = len(plan["create"])

    applied: list[str] = []
    if args.apply:
        for relative, kind, expected in assets:
            target = root / relative
            if kind == "directory":
                if not target.is_dir():
                    target.mkdir(parents=True, exist_ok=False)
                    applied.append(relative)
                continue
            if target.exists() or target.is_symlink():
                continue  # never overwrite existing repo-local content
            target.parent.mkdir(parents=True, exist_ok=True)
            temporary = target.parent / f".{target.name}.init.tmp"
            temporary.write_bytes(expected or b"")
            os.replace(temporary, target)
            applied.append(relative)

    template_files = sorted(
        p.name for p in (root / TEMPLATES_ROOT).iterdir() if p.is_file()
    ) if (root / TEMPLATES_ROOT).is_dir() else []
    receipt = {
        "skill": "run-dev-graph-init",
        "mode": "apply" if args.apply else "preview",
        "repository_id": repository_id,
        "worktree_id": context["worktree_id"],
        "authority": {
            "content": "caller-repository",
            "code": "plugin-root-read-only",
            "stored_paths": "repository-relative",
        },
        "content_roots": dict(CONTENT_ROOTS),
        "local_state": dict(LOCAL_STATE),
        "templates_root": TEMPLATES_ROOT,
        "planned_changes": planned_changes,
        "planned_change_paths": [item["path"] for item in plan["create"]],
        "created": sorted(applied),
        "preserved": plan["preserved"],
        "migration_preview": plan["migration_preview"],
        "template_contract": {
            "enumerated": enumerated,
            "enumerated_missing_in_target": [
                name for name in enumerated if name not in template_files
            ],
            "shipped_total": len(shipped),
            "target_total": len(template_files),
        },
        "hook_source": hooks["effective_source"],
        "hook_diagnostics": hooks,
        "diagnostics": context["diagnostics"],
    }
    receipt["forbidden_content_findings"] = scan_forbidden(
        root, [CONFIG_PATH, LOCAL_STATE["graph"]]
    )
    Path(args.receipt).write_text(
        json.dumps(receipt, ensure_ascii=False, sort_keys=True, indent=2) + "\n", encoding="utf-8"
    )
    print(json.dumps(
        {
            "mode": receipt["mode"],
            "planned_changes": planned_changes,
            "created": len(applied),
            "preserved": len(plan["preserved"]),
            "migration_preview": len(plan["migration_preview"]),
            "template_enumerated_missing": receipt["template_contract"]["enumerated_missing_in_target"],
            "forbidden_content_findings": receipt["forbidden_content_findings"],
            "hook_source": receipt["hook_source"],
        },
        ensure_ascii=False,
        sort_keys=True,
    ))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ContractError, OSError, subprocess.CalledProcessError) as exc:
        print(f"init failed: {exc}", file=sys.stderr)
        raise SystemExit(1)

